def transform(grid):
    g=[row[:] for row in grid]
    # Find the rectangular frame bounds (color 3 at top and bottom edges).
    rs=[r for r,row in enumerate(grid) if 3 in row]
    cs=[c for c in range(len(grid[0])) if any(grid[r][c]==3 for r in range(len(grid)))]
    top,bottom=min(rs),max(rs); left,right=min(cs),max(cs)
    # Interior bands: outer fill, inset ring, then center emblem.
    for r in range(top+1,bottom):
        for c in range(left+1,right):
            g[r][c]=4
    for r in range(top+2,bottom-1):
        for c in range(left+2,right-1):
            if r in (top+2,bottom-2) or c in (left+2,right-2):
                g[r][c]=2
    # Retain a central 3 pixel if present in the input.
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==3 and top<r<bottom and left<c<right:
                g[r][c]=3
    return g
